/// <summary>
/// Extension of ChequeDP
/// </summary>
[ExtensionOf(classStr(ChequeDP))]
final class METChequeDP_Extension
{
}

Method.Source:
    /// <summary>
    /// CoC extension.
    /// </summary>
    protected void populateChequeTmp()
    {
        next populateChequeTmp();

        if( chequeReportType == ChequeFormType::MET_AU_ANZ          // MPJ-7141
        ||  chequeReportType == ChequeFormType::MET_AU_ANZMulti )   //MPJ_5244_CommunityChestChequeLayout DCP 04/02/2022
        {
            this.METpopulateChequeTmp_AU_ANZ();
        }
    }

    /// <summary>
    /// Additional fields and updates for AU ANZ format.
    /// </summary>
    private void METpopulateChequeTmp_AU_ANZ()
    {
        str digitAt(int pos)
        {
            str ret = num2Str(trunc(chequeTmp.AmountCur), 999, 0, 0, 0);
            ret = subStr(ret, strLen(ret) - pos + 1, 1);
            return ret;
        }
        
        chequeTmp.Amount = strFmt('%1', chequeTmp.AmountCur);

        // MPJ_7141_CommunityChestChequeLayout
        chequeTmp.METNumber_Millions            = (chequeTmp.AmountCur >= 1000000) ? any2Str(trunc(chequeTmp.AmountCur / 1000000)) : METHelper::getWord(digitAt(0));
        chequeTmp.METNumber_HundredThousands    = METHelper::getWord(digitAt(6));
        chequeTmp.METNumber_TenThousands        = METHelper::getWord(digitAt(5));
        chequeTmp.METNumber_Thousands           = METHelper::getWord(digitAt(4));
        chequeTmp.METNumber_Hundreds            = METHelper::getWord(digitAt(3));
        chequeTmp.METNumber_Tens                = METHelper::getWord(digitAt(2));
        chequeTmp.METNumber_Units               = METHelper::getWord(digitAt(1));
        chequeTmp.METNumber_Cents               = any2Str(real2int(frac(chequeTmp.AmountCur) * 100));


        chequeTmp.DateStr = date2str(
            tmpChequePrintout.MaturityDate, 
            123, 
            2, 
            DateSeparator::Slash, 
            2, 
            DateSeparator::Slash,
            4, 
            DateFlags::None);
                
    }
